steps.script:
var mm = tree.root.get_node("/root/MainMenu")
var n = mm.get_node_or_null("TutorialNudge")
if n != null and n.visible:
	n.get_node("Margin/VBox/Footer/DismissNudgeButton").pressed.emit()
return true

var l = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/MovementScrollContainer/MovementPanel/Section1_UnitList/MovementUnitList")
if l == null:
	return false
var texts = []
for i in range(l.item_count):
	texts.append(str(l.get_item_text(i)))
return l.item_count > 0 and "|".join(texts).contains("Battlewagon")

var o = tree.root.get_node("/root/TutorialOverlay")
var t = str(o.current_body_text())
return t.contains("[Y]") and not t.contains("[B]")

var o = tree.root.get_node("/root/TutorialOverlay")
var t = str(o.current_body_text())
return t.contains("pause menu") and t.contains("Controller") and not t.contains("Shift")

var m = tree.root.get_node("/root/Main/SettingsMenu")
var names = []
for b in m._tab_buttons:
	names.append(str(b.text))
return names

var m = tree.root.get_node("/root/Main/SettingsMenu")
var rows = m._pad_role_buttons
return rows.has("pad_pause") and rows.has("pad_select") and rows.size() >= 10

var pr = tree.root.get_node("/root/PadRouter")
var mc = tree.current_scene.movement_controller
var models = GameState.get_unit("U_GRETCHIN_T").get("models", [])
var alive = 0
for m in models:
	if m.get("alive", true):
		alive += 1
return alive > 1 and pr.group_carry_active and mc.selected_models.size() == alive

var md = PhaseManager.current_phase_instance.get_active_move_data("U_GRETCHIN_T")
var staged := {}
for sm in md.get("staged_moves", []):
	staged[str(sm.get("model_id", ""))] = true
var models = GameState.get_unit("U_GRETCHIN_T").get("models", [])
var alive = 0
for m in models:
	if m.get("alive", true):
		alive += 1
return alive > 1 and staged.size() == alive
